import { adultChildLifeView } from './adult-child-view.js';
import { agingPolicy } from './aging-policy-v25.js';
import { questReturnForecast } from './quest-records.js';
import { RPG_FACTIONS_V27 } from './rpg-depth-v27.js';
import { HOUSEHOLD_FOCI, HOUSEHOLD_LIFESTYLES, householdCostPreview } from './budget.js';

const words=v=>typeof v==='string'?v:v?.text||v?.description||'';
const site=(s,id)=>s.world.locations.find(p=>p.id===id)?.name||'the recorded settlement';
export function lifeChapterView(s){
 const r=s.careers?.records?.[s.hero.profession],children=(s.life?.children||[]).filter(p=>p.alive!==false);
 if(s.age<3)return {title:'The years you are held',concern:'Familiar adults make the decisions. Watch this household as your first years unfold.'};
 if(s.age<18)return {title:s.age<10?'Learning the shape of home':'Finding your own voice',concern:s.education?.enrolled?'Your lessons, friendships and interests have room to grow together.':'Learning can begin with people and places around you. Formal school requires enrollment and real attendance.'};
 if(s.careers?.masterworks.some(w=>w.authorName===s.hero.name))return {title:'What your work leaves behind',concern:'Your signed work has a recorded recipient. Your own days, relationships and new interests remain open.'};
 if(r?.mastery>=3||children.some(c=>s.day-c.bornDay>=18*365))return {title:'Experience to share',concern:'Your work and the people growing around you can lead to teaching, shared projects or a quieter season.'};
 if(s.life?.partnerId||children.length)return {title:'A life shared',concern:'Household time, your own interests and willing company share a real calendar. Family members keep their own wishes.'};
 if(r?.workedDays>=30)return {title:'A practice taking shape',concern:`Your ${s.hero.profession.toLowerCase()} work has ${r.workedDays} recorded days. Build on it, change direction or make room for another part of life.`};
 return {title:'A beginning of your own',concern:'Choose what belongs in your days: work, study, friends, care, a home or the road. No path is required.'};
}
export function lifeCalendarRows(s){
 const rows=[],add=(id,day,kind,title,detail,locationId)=>{if(Number.isSafeInteger(day)&&day>=s.day)rows.push({id,day,kind,title,detail,locationId});};
 const birth=s.timeline?.mode==='birth'?(s.timeline.birthDay||0):-18*365;
 const nextBirthday=born=>born+(Math.floor((s.day-born)/365)+1)*365;
 add('birthday',nextBirthday(birth),'Birthday','Your next birthday','Time may pause for a birthday decision.');
 for(const p of s.life?.children||[])if(p.alive!==false&&Number.isSafeInteger(p.bornDay))add('birthday:'+p.id,nextBirthday(p.bornDay),'Birthday',p.name+'’s birthday','Their age and own development follow their recorded birth date.');
 for(const o of s.obligations||[])if(!o.resolved&&!o.missed){const d=o.dueDay??o.deadlineDay;add('promise:'+o.id,d,'Deadline',o.title,o.description,o.locationId);}
 const c=s.careers?.active;if(c&&['accepted','ready'].includes(c.status))add('commission:'+c.id,c.dueDay,'Deadline','Commission for '+c.customerName,'The agreed late-payment terms apply after this date.',c.locationId);
 for(const q of questReturnForecast(s))add('return:'+q.id,Math.max(s.day,q.dueDay),q.paused?'Paused return':'Available return',q.title,q.ready?'Ready to revisit when you choose. No new work has been accepted.':q.personName+' can be revisited at age '+q.nextAge+'.',q.locationId);
 for(const [key,label]of [['restUntil','Rest care'],['medicineUntil','Medical care'],['supportUntil','Emotional support']])if(s.health?.care?.[key]>s.day)add('care:'+key,s.health.care[key],'Care window',label+' review','This support window ends here; symptom recovery follows its own checks.');
 return rows.sort((a,b)=>a.day-b.day||a.id.localeCompare(b.id));
}
export function independentLifeRows(s){
 const known=new Set([...(s.life?.people||[]).map(p=>p.id),...(s.life?.children||[]).map(p=>p.id),...Object.keys(s.conversations?.meetings||{})]);
 const people=[...(s.lineage?.people||[]),...(s.society?.people||[])].filter((p,i,a)=>(known.has(p.id)||known.has(p.localId))&&a.findIndex(q=>q.id===p.id)===i);
 return people.map(p=>{const own=adultChildLifeView(s,p),id=p.localId||p.id;return own?{id,name:p.name,summary:own.summary,detail:[own.progress,own.support,own.residence,own.suspended?'Progress is suspended while their actual circumstances are unavailable.':''].filter(Boolean).join(' ')}:p.memories?.length?{id,name:p.name,summary:p.occupation?`${p.name} has their own ${p.occupation.toLowerCase()} work.`:`${p.name} has their own life.`,detail:words(p.memories.at(-1))}:null;}).filter(Boolean);
}
export function consequenceRows(s){
 const generation=s.dynasty?.generation||1;
 return (s.journal||[]).filter(r=>(r.generation||1)===generation&&['personal','relationships','family','career','crime','justice','community','quest','rpg','legacy','childhood'].includes(r.tag)).slice(-24).reverse().map(r=>({id:r.id,title:r.title,text:r.text,day:r.day,source:'Recorded life entry'}));
}
export function renderIndependentLives(s,ui){
 const rows=independentLifeRows(s);if(!rows.length)return '';
 return `<details class="panel independent-lives"><summary>Their own lives · ${rows.length}</summary><p>Recorded plans and news shared with this household. Opening this page makes no decision for anyone.</p>${rows.slice(0,12).map(p=>`<article class="remembered-entry"><h3>${ui.e(p.name)}</h3><p>${ui.e(p.summary)}</p><p>${ui.e(p.detail)}</p>${ui.button('Find their record','show-contact',p.id,'ghost small')}</article>`).join('')}${rows.length>12?'<p>Find further people in Relationships.</p>':''}</details>`;
}
export function renderLifeContext(s,actions,ui){
 const {e,button,date}=ui,c=lifeChapterView(s),calendar=lifeCalendarRows(s),r=s.careers?.records?.[s.hero.profession],policy=agingPolicy(s.hero),budget=householdCostPreview(s,7);
 const actionsOf=regex=>actions.filter(a=>regex.test(a.id)).map(a=>`<div>${button(e(a.label),'activity',a.id,'secondary small',Boolean(a.disabledReason))}<p class="small-copy">${e(a.disabledReason||a.description)}</p></div>`).join('');
 const works=(s.careers?.masterworks||[]).filter(w=>w.recipient==='household'),local=s.realm?.sites?.[s.locationId],incident=(s.legal?.incidents||[]).find(i=>i.locationId===s.locationId);
 const records=consequenceRows(s),occasions=actions.filter(a=>a.id==='life_family'||a.id==='leisure_circle'||/^family_(visit|time|remember)/.test(a.id));
 return `<section class="panel life-chapter" data-life-chapter><span class="eyebrow">THIS PART OF YOUR LIFE</span><h2>${e(c.title)}</h2><p>${e(c.concern)}</p><p class="small-copy">Chronological age ${s.age}. Portrait stages begin at 40, 55 and 65; ${e(policy.ancestry)} physiology uses its own later-life milestones (elder stage ${policy.elder}). Saved birth and death dates are preserved.</p></section><section class="panel life-calendar" data-life-calendar><h2>Household calendar</h2><p>Recorded dates and availability. Returns are invitations; deadlines retain their agreed terms.</p>${calendar.slice(0,16).map(q=>`<article class="remembered-entry"><small>${e(q.kind)} · ${e(date(q.day))} · ${q.day-s.day} days away</small><h3>${e(q.title)}</h3><p>${e(q.detail)}</p>${q.locationId?button('Find recorded place','quest-location',q.locationId,'ghost small'):''}</article>`).join('')}${calendar.length>16?`<p>${calendar.length-16} later dates remain in the relevant records.</p>`:''}</section>${renderIndependentLives(s,ui)}${occasions.length?`<details class="panel household-occasions"><summary>Time to keep together</summary><p>Ordinary company, shared memories and household occasions remain optional. People keep their own wishes; an invitation is not an obligation.</p>${ui.actionCards?.(occasions)||actionsOf(/^(life_family|leisure_circle|family_(visit|time|remember))$/)}</details>`:''}${actions.some(a=>a.id.startsWith('conversations_repair_'))?`<section class="panel" data-restoration-options><h2>Make good on an earlier account</h2><p>These are proposals for actual restoration work. The original harm remains recorded; attendance buys no affection or forgiveness.</p>${actionsOf(/^conversations_repair_/)}</section>`:''}<details class="panel household-planning"><summary>Household priorities &amp; living costs</summary><p>${e(HOUSEHOLD_FOCI.find(f=>f.id===s.life?.focus)?.label||'Your current focus')} · ${e(HOUSEHOLD_LIFESTYLES.find(l=>l.id===s.life?.lifestyle)?.label||'Your current living standard')}.</p><p>Current provisions and upkeep: ${budget.annual} Gold per adult year. The next seven actual days add about ${budget.additionalCost} Gold at current circumstances. Direct action fees and wages are separate; future changes can alter this estimate.</p>${actionsOf(/^budget_(focus|lifestyle)_/)}</details><details class="panel"><summary>How people know your work</summary><p>Professional reputation: ${r?.reputation??0}${s.hero.profession!=='Unemployed'?' in '+e(s.hero.profession):' · no current profession'}. ${r?.workedDays||0} actual work days; ${r?.commissions||0} delivered commissions.</p><p>Local standing in ${e(site(s,s.locationId))}: ${Number.isFinite(local?.standing)?local.standing:'no separate standing score recorded'}. ${incident?e(incident.description)+' Evidence '+incident.evidence+'.':'No outstanding report is recorded here.'}</p>${(s.rpg?.factions||[]).filter(f=>f.rank>0).map(f=>`<p>${e(RPG_FACTIONS_V27.find(d=>d.id===f.id)?.name||'A known faction')} · rank ${f.rank}.</p>`).join('')}<p class="small-copy">Professional standing, local law, faction membership and personal boundaries remain separate. Private knowledge is shared only through its own witnessed events.</p></details>${works.length?`<details class="panel" data-heirloom-provenance><summary>Household works &amp; heirlooms</summary>${works.slice(-12).map(w=>`<article class="remembered-entry"><h3>${e(w.name)}</h3><p>Made by ${e(w.authorName)}, ${e(date(w.day))}, ${e(site(s,w.locationId))}. Quality ${w.quality}. Entrusted to the household.</p><p>Its authorship and household custody survive succession; its maker’s skill is not inherited.</p></article>`).join('')}</details>`:''}<details class="panel consequence-ledger" data-consequence-ledger><summary>Because of earlier events · ${records.length} recent accounts</summary><p>These are the words recorded when events happened. Reading changes no relationship, reward or legal outcome.</p>${records.map(r=>`<article class="remembered-entry"><small>${e(date(r.day))} · ${e(r.source)}</small><h3>${e(r.title)}</h3><p>${e(r.text)}</p></article>`).join('')||'<p>No matching account has yet been recorded.</p>'}</details>`;
}
